// test.cpp
//
// Compare two convex-convex polygon intersection algorithms:
//
//   1) O'Rourke's "ConvexIntersect" (Chapter 7, "Computational Geometry in C",
//      2nd ed., 1997), adapted from C to C++ and from int to double.  The
//      original code uses PostScript printf to emit the result; here we
//      collect the output vertices into a std::vector<double[2]> instead.
//
//   2) The CGAL-based "convex_polygon_intersection" used in simplify.cpp:
//      it converts to an IntersectKernel (Filtered_kernel<Simple_cartesian<double>>),
//      collects every P-vertex in Q, every Q-vertex in P, and every segment
//      intersection, deduplicates, and takes the convex hull.
//
// Both algorithms are timed on a battery of random convex-convex test cases
// and the result vertices are compared for equality.  We also include a few
// hand-picked geometric edge cases (disjoint, one-inside-the-other, touching,
// edge-overlap) to stress the O'Rourke code's special-case handling.

#include <CGAL/Exact_predicates_exact_constructions_kernel.h>
#include <CGAL/Polygon_2.h>
#include <CGAL/Simple_cartesian.h>
#include <CGAL/Filtered_kernel.h>
#include <CGAL/convex_hull_2.h>
#include <CGAL/intersections.h>

#include <algorithm>
#include <cassert>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <map>
#include <numeric>
#include <optional>
#include <random>
#include <set>
#include <sstream>
#include <string>
#include <tuple>
#include <utility>
#include <variant>
#include <vector>

// ===========================================================================
//  Part 1: O'Rourke's ConvexIntersect, adapted to C++ / double
// ===========================================================================
//
// Original C code (Joseph O'Rourke, December 1997).  Converted:
//   * All tPointi / int coordinates -> double
//   * PMAX dynamic -> std::vector
//   * PostScript printf output -> std::vector<std::array<double,2>>
//   * `bool` typedef replaced with C++ `bool`
//   * `ReadPoly` (stdin) replaced by populating the input vector directly
//
// Result is a list of vertices in CCW order (the O'Rourke code closes the
// polygon by repeating p0 on exit, so the output may have a repeated first
// vertex at the end; we strip that below).

namespace orourke {

using Point = std::array<double, 2>;
using Polygon = std::vector<Point>;

enum class InFlag { Pin, Qin, Unknown };

static double cross2D(const Point& a, const Point& b, const Point& c) {
    return (b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1]);
}

// Sign of triangle area; threshold 0.5 mirrors the original's int rounding
// tolerance (area2 is an integer when inputs are integer, so 0.5 is a
// half-unit guard band).  We keep the same constant for behavioural parity
// even though the inputs are now doubles.
static int area_sign(const Point& a, const Point& b, const Point& c) {
    double area2 = cross2D(a, b, c);
    if (area2 > 0.5) return 1;
    if (area2 < -0.5) return -1;
    return 0;
}

static bool collinear(const Point& a, const Point& b, const Point& c) {
    return area_sign(a, b, c) == 0;
}

static bool between(const Point& a, const Point& b, const Point& c) {
    if (a[0] != b[0])
        return ((a[0] <= c[0]) && (c[0] <= b[0])) ||
               ((a[0] >= c[0]) && (c[0] >= b[0]));
    return ((a[1] <= c[1]) && (c[1] <= b[1])) ||
           ((a[1] >= c[1]) && (c[1] >= b[1]));
}

static double dot(const Point& a, const Point& b) {
    return a[0] * b[0] + a[1] * b[1];
}

static void sub_vec(const Point& a, const Point& b, Point& c) {
    c[0] = a[0] - b[0];
    c[1] = a[1] - b[1];
}

// Returns one of: 'e' (collinear overlap), 'v' (endpoint on other segment),
// '1' (proper intersection), '0' (no intersection).
// 'p' is the first intersection point, 'q' is the second (only meaningful
// when code == 'e').
static char parallel_int(const Point& a, const Point& b,
                          const Point& c, const Point& d,
                          Point& p, Point& q) {
    if (!collinear(a, b, c)) return '0';

    if (between(a, b, c) && between(a, b, d)) {
        p = c; q = d; return 'e';
    }
    if (between(c, d, a) && between(c, d, b)) {
        p = a; q = b; return 'e';
    }
    if (between(a, b, c) && between(c, d, b)) {
        p = c; q = b; return 'e';
    }
    if (between(a, b, c) && between(c, d, a)) {
        p = c; q = a; return 'e';
    }
    if (between(a, b, d) && between(c, d, b)) {
        p = d; q = b; return 'e';
    }
    if (between(a, b, d) && between(c, d, a)) {
        p = d; q = a; return 'e';
    }
    return '0';
}

static char seg_seg_int(const Point& a, const Point& b,
                         const Point& c, const Point& d,
                         Point& p, Point& q) {
    char code = '?';
    double denom = a[0] * (d[1] - c[1]) +
                   b[0] * (c[1] - d[1]) +
                   d[0] * (b[1] - a[1]) +
                   c[0] * (a[1] - b[1]);

    if (denom == 0.0)
        return parallel_int(a, b, c, d, p, q);

    double num = a[0] * (d[1] - c[1]) +
                 c[0] * (a[1] - d[1]) +
                 d[0] * (c[1] - a[1]);
    if (num == 0.0 || num == denom) code = 'v';
    double s = num / denom;

    num = -(a[0] * (c[1] - b[1]) +
            b[0] * (a[1] - c[1]) +
            c[0] * (b[1] - a[1]));
    if (num == 0.0 || num == denom) code = 'v';
    double t = num / denom;

    if      ((0.0 < s) && (s < 1.0) && (0.0 < t) && (t < 1.0)) code = '1';
    else if ((0.0 > s) || (s > 1.0) || (0.0 > t) || (t > 1.0)) code = '0';

    p[0] = a[0] + s * (b[0] - a[0]);
    p[1] = a[1] + s * (b[1] - a[1]);
    return code;
}

// Append a vertex `v` to `output` if `inside` is true.  This is the print-
// step of the original `Advance`.
static int advance(int a, int& aa, int n, bool inside,
                    const Point& v, Polygon& output) {
    if (inside) output.push_back(v);
    aa++;
    return (a + 1) % n;
}

// Toggle the in/out flag when an intersection is hit.
static InFlag in_out(const Point& p, InFlag inflag, int aHB, int bHA) {
    if      (aHB > 0) return InFlag::Pin;
    else if (bHA > 0) return InFlag::Qin;
    else              return inflag;
}

// O'Rourke's ConvexIntersect, adapted.  Returns the intersection polygon
// (may be empty).  If P is contained in Q (or vice versa) and they share no
// boundary crossings, the inner polygon is returned verbatim.
Polygon convex_intersect(const Polygon& Pin, const Polygon& Qin) {
    int n = (int)Pin.size();
    int m = (int)Qin.size();
    if (n < 3 || m < 3) return {};

    int a = 0, b = 0;
    int aa = 0, ba = 0;
    InFlag inflag = InFlag::Unknown;
    bool first_point = true;

    Polygon out;
    Point p0{};
    bool shared_edge = false;          // 'e'-overlap with opposite orientation
    Point shared_p{}, shared_q{};

    auto finish = [&](bool closed) {
        if (closed && !first_point) out.push_back(p0);  // close polygon
    };

    do {
        int a1 = (a + n - 1) % n;
        int b1 = (b + m - 1) % m;

        Point A, B;
        sub_vec(Pin[a], Pin[a1], A);
        sub_vec(Qin[b], Qin[b1], B);

        const Point origin{0.0, 0.0};
        int cross = area_sign(origin, A, B);
        int aHB   = area_sign(Qin[b1], Qin[b], Pin[a]);
        int bHA   = area_sign(Pin[a1], Pin[a], Qin[b]);

        Point p{}, q{};
        char code = seg_seg_int(Pin[a1], Pin[a], Qin[b1], Qin[b], p, q);

        if (code == '1' || code == 'v') {
            if (inflag == InFlag::Unknown && first_point) {
                aa = ba = 0;
                first_point = false;
                p0 = p;
            }
            out.push_back(p);
            inflag = in_out(p, inflag, aHB, bHA);
        }

        // Special case: A & B overlap and oppositely oriented -> shared edge
        if ((code == 'e') && (dot(A, B) < 0)) {
            shared_edge = true;
            shared_p = p; shared_q = q;
            break;
        }

        // Special case: A & B parallel and separated
        if ((cross == 0) && (aHB < 0) && (bHA < 0)) {
            return {};
        }

        // Special case: A & B collinear -> advance without printing
        if ((cross == 0) && (aHB == 0) && (bHA == 0)) {
            if (inflag == InFlag::Pin)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qin[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pin[a], out);
        } else if (cross >= 0) {
            if (bHA > 0)
                a = advance(a, aa, n, inflag == InFlag::Pin, Pin[a], out);
            else
                b = advance(b, ba, m, inflag == InFlag::Qin, Qin[b], out);
        } else {  // cross < 0
            if (aHB > 0)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qin[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pin[a], out);
        }
    } while (((aa < n) || (ba < m)) && (aa < 2 * n) && (ba < 2 * m));

    if (shared_edge) {
        out.push_back(shared_p);
        out.push_back(shared_q);
    } else {
        finish(!first_point);
    }

    if (inflag == InFlag::Unknown && first_point) {
        // boundaries do not cross: P is inside Q, or Q is inside P, or they
        // touch at a single point.  The original code does not implement
        // these special cases; we add minimal handling so the test can
        // exercise them.
        // Detect containment by sampling a single vertex of P.
        if (point_in_convex_poly(Pin[0], Qin)) {
            return Pin;
        }
        if (point_in_convex_poly(Qin[0], Pin)) {
            return Qin;
        }
        return {};
    }

    // Strip trailing duplicate (== p0) if any
    if (out.size() >= 2) {
        const auto& first = out.front();
        const auto& last = out.back();
        if (std::fabs(first[0] - last[0]) < 1e-9 &&
            std::fabs(first[1] - last[1]) < 1e-9) {
            out.pop_back();
        }
    }
    return out;
}

}  // namespace orourke

// ===========================================================================
//  Part 2: CGAL-based convex polygon intersection (mirrors simplify.cpp)
// ===========================================================================
//
// Extracted from simplify.cpp::convex_polygon_intersection.  Uses
// Filtered_kernel<Simple_cartesian<double>> for the predicates and a
// boundary-point-collecting + convex hull strategy.

namespace cgal_impl {

using IntersectKernel  = CGAL::Filtered_kernel<CGAL::Simple_cartesian<double>>;
using IntersectPoint   = IntersectKernel::Point_2;
using IntersectSegment = IntersectKernel::Segment_2;

static IntersectPoint to_intersect(double x, double y) {
    return IntersectPoint(x, y);
}

static bool point_in_polygon(const IntersectPoint& p,
                              const std::vector<IntersectPoint>& poly) {
    int n = (int)poly.size();
    for (int i = 0; i < n; i++) {
        const auto& a = poly[i];
        const auto& b = poly[(i + 1) % n];
        if (!CGAL::left_turn(a, b, p)) return false;
    }
    return true;
}

static std::optional<IntersectPoint>
segment_intersection(const IntersectPoint& p1, const IntersectPoint& p2,
                      const IntersectPoint& q1, const IntersectPoint& q2) {
    auto inter = CGAL::intersection(IntersectSegment(p1, p2),
                                    IntersectSegment(q1, q2));
    if (inter && std::holds_alternative<IntersectPoint>(*inter)) {
        return std::get<IntersectPoint>(*inter);
    }
    return std::nullopt;
}

std::vector<std::array<double, 2>>
convex_polygon_intersection(const std::vector<std::array<double, 2>>& P_in,
                              const std::vector<std::array<double, 2>>& Q_in) {
    std::vector<IntersectPoint> P, Q;
    P.reserve(P_in.size());
    Q.reserve(Q_in.size());
    for (auto& v : P_in) P.push_back(to_intersect(v[0], v[1]));
    for (auto& v : Q_in) Q.push_back(to_intersect(v[0], v[1]));

    int n = (int)P.size();
    int m = (int)Q.size();
    if (n < 3 || m < 3) return {};

    std::vector<IntersectPoint> candidates;
    std::set<std::pair<double, double>> seen;
    auto add_unique = [&](const IntersectPoint& p) {
        double x = CGAL::to_double(p.x());
        double y = CGAL::to_double(p.y());
        if (seen.insert({x, y}).second) candidates.push_back(p);
    };

    for (int i = 0; i < n; i++)
        if (point_in_polygon(P[i], Q)) add_unique(P[i]);
    for (int j = 0; j < m; j++)
        if (point_in_polygon(Q[j], P)) add_unique(Q[j]);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            auto inter = segment_intersection(
                P[i], P[(i + 1) % n], Q[j], Q[(j + 1) % m]);
            if (inter) add_unique(*inter);
        }
    }
    if (candidates.size() < 3) return {};

    std::vector<IntersectPoint> hull;
    CGAL::convex_hull_2(candidates.begin(), candidates.end(),
                        std::back_inserter(hull));
    if (hull.size() < 3) return {};

    std::vector<std::array<double, 2>> result;
    result.reserve(hull.size());
    for (auto& hp : hull) {
        result.push_back({CGAL::to_double(hp.x()),
                          CGAL::to_double(hp.y())});
    }
    return result;
}

}  // namespace cgal_impl

// ===========================================================================
//  Shared helpers: convex-polygon generation, point-in-convex-polygon test,
//  polygon area, equality up to cyclic rotation, etc.
// ===========================================================================

using Point   = std::array<double, 2>;
using Polygon = std::vector<Point>;

// Deterministic per-test RNG so that the O'Rourke and CGAL code paths see
// identical input across iterations of the timing loop.
static std::mt19937& global_rng() {
    static thread_local std::mt19937 rng{0xC0FFEE};
    return rng;
}

// Generate a random convex polygon with `n` vertices centred near the origin
// in roughly the bounding square [-scale, scale]^2.  Built by sampling
// random angles in [0, 2pi) and random radii in [r_min, r_max] and sorting
// the points by angle (a standard convex-polygon sampler).
Polygon random_convex(std::size_t n, double scale, double r_min_frac = 0.3) {
    if (n < 3) n = 3;
    auto& rng = global_rng();
    std::uniform_real_distribution<double> U(0.0, 1.0);
    std::vector<Point> pts;
    pts.reserve(n);
    double r_min = scale * r_min_frac;
    double r_max = scale;
    for (std::size_t i = 0; i < n; i++) {
        double theta = U(rng) * 2.0 * M_PI;
        double r = r_min + U(rng) * (r_max - r_min);
        pts.push_back({r * std::cos(theta), r * std::sin(theta)});
    }
    std::sort(pts.begin(), pts.end(),
              [](const Point& a, const Point& b) {
                  return std::atan2(a[1], a[0]) < std::atan2(b[1], b[0]);
              });
    return pts;
}

// Signed area; positive when CCW.
static double signed_area(const Polygon& p) {
    double a = 0.0;
    int n = (int)p.size();
    for (int i = 0; i < n; i++) {
        const auto& u = p[i];
        const auto& v = p[(i + 1) % n];
        a += u[0] * v[1] - v[0] * u[1];
    }
    return a / 2.0;
}

// Translate a polygon by a random amount in [-shift, shift]^2.
Polygon shift(const Polygon& in, double shift_amt) {
    auto& rng = global_rng();
    std::uniform_real_distribution<double> U(-shift_amt, shift_amt);
    double dx = U(rng), dy = U(rng);
    Polygon out;
    out.reserve(in.size());
    for (auto& p : in) out.push_back({p[0] + dx, p[1] + dy});
    return out;
}

// Hand-picked CCW convex polygon.
Polygon make_square(double cx, double cy, double h) {
    return {{cx - h, cy - h}, {cx + h, cy - h},
            {cx + h, cy + h}, {cx - h, cy + h}};
}
Polygon make_triangle(double cx, double cy, double r) {
    return {{cx, cy + r},
            {cx + r * 0.86602540378, cy - r * 0.5},
            {cx - r * 0.86602540378, cy - r * 0.5}};
}

// O(n) convex-polygon point-in-poly test: a point is inside the convex hull
// iff it is to the left of every CCW edge.  Boundary counts as inside.
bool point_in_convex_poly(const Point& p, const Polygon& poly) {
    int n = (int)poly.size();
    for (int i = 0; i < n; i++) {
        const auto& a = poly[i];
        const auto& b = poly[(i + 1) % n];
        if ((b[0] - a[0]) * (p[1] - a[1]) -
            (b[1] - a[1]) * (p[0] - a[0]) < -1e-12)
            return false;
    }
    return true;
}

// Reorder a polygon so its lowest-lex vertex comes first.  Helps compare
// vertex sets that are equal up to cyclic rotation.
Polygon canonical(const Polygon& in) {
    if (in.empty()) return in;
    int n = (int)in.size();
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (in[i][0] < in[best][0] ||
            (in[i][0] == in[best][0] && in[i][1] < in[best][1])) {
            best = i;
        }
    }
    Polygon out;
    out.reserve(n);
    for (int k = 0; k < n; k++) out.push_back(in[(best + k) % n]);
    return out;
}

bool polygons_equal(const Polygon& A, const Polygon& B, double tol = 1e-6) {
    if (A.size() != B.size()) return false;
    auto ca = canonical(A), cb = canonical(B);
    for (std::size_t i = 0; i < ca.size(); i++) {
        if (std::fabs(ca[i][0] - cb[i][0]) > tol) return false;
        if (std::fabs(ca[i][1] - cb[i][1]) > tol) return false;
    }
    return true;
}

// Force CCW orientation.
Polygon ensure_ccw(const Polygon& p) {
    if (signed_area(p) < 0) {
        Polygon r(p.rbegin(), p.rend());
        return r;
    }
    return p;
}

// ===========================================================================
//  Test cases
// ===========================================================================

struct TestCase {
    std::string name;
    Polygon P, Q;
};

std::vector<TestCase> build_test_cases() {
    std::vector<TestCase> cases;

    // Hand-picked edge cases -----------------------------------------------
    {
        TestCase t; t.name = "disjoint_far";
        t.P = make_square(-10, 0, 1);
        t.Q = make_square( 10, 0, 1);
        cases.push_back(std::move(t));
    }
    {
        TestCase t; t.name = "overlap_square_in_square";
        t.P = make_square(0, 0, 2);
        t.Q = make_square(1, 0, 1.5);
        cases.push_back(std::move(t));
    }
    {
        TestCase t; t.name = "one_inside_other";
        t.P = make_square(0, 0, 5);
        t.Q = make_square(0.3, -0.2, 1);
        cases.push_back(std::move(t));
    }
    {
        TestCase t; t.name = "touching_at_corner";
        t.P = make_square(0, 0, 1);
        t.Q = make_square(2, 1, 1);  // shares corner (1,1)
        cases.push_back(std::move(t));
    }
    {
        TestCase t; t.name = "edge_overlap_opposite";
        // Two squares sharing a full edge, opposite orientations
        t.P = {{-1, -1}, { 1, -1}, { 1,  1}, {-1,  1}};
        t.Q = {{ 1, -1}, {-1, -1}, {-1,  1}, { 1,  1}};
        cases.push_back(std::move(t));
    }
    {
        TestCase t; t.name = "triangle_intersects_square";
        t.P = make_triangle(0, 0, 2);
        t.Q = make_square(0, 0, 1.5);
        cases.push_back(std::move(t));
    }

    // Random pairs of varying sizes ---------------------------------------
    std::vector<std::pair<int, int>> sizes = {
        {3, 3}, {4, 4}, {8, 8}, {16, 16}, {32, 32},
        {4, 32}, {32, 4}, {64, 64}, {128, 128}, {256, 256},
    };
    auto& rng = global_rng();
    std::uniform_real_distribution<double> U(0.0, 1.0);
    for (auto [na, nb] : sizes) {
        for (int rep = 0; rep < 3; rep++) {
            TestCase t;
            t.name = "rand_n" + std::to_string(na) + "_m" +
                     std::to_string(nb) + "_r" + std::to_string(rep);
            t.P = random_convex(na, 100.0);
            // Random shift; some pairs will be disjoint.
            double shift_amt = (U(rng) < 0.3) ? 250.0 : 30.0;
            t.Q = shift(random_convex(nb, 100.0), shift_amt);
            cases.push_back(std::move(t));
        }
    }
    return cases;
}

// ===========================================================================
//  Timer
// ===========================================================================

template <typename F>
double time_ms(F&& f, int repeats) {
    using clk = std::chrono::high_resolution_clock;
    auto t0 = clk::now();
    for (int i = 0; i < repeats; i++) f();
    auto t1 = clk::now();
    return std::chrono::duration<double, std::milli>(t1 - t0).count() / repeats;
}

// ===========================================================================
//  Main
// ===========================================================================

int main(int argc, char** argv) {
    int repeats = 200;          // trials per case for timing
    int repeats_small = 1000;   // for very small polygons
    if (argc > 1) repeats = std::atoi(argv[1]);

    auto cases = build_test_cases();

    std::cout << std::fixed << std::setprecision(3);
    std::cout << "=================================================================\n";
    std::cout << "  Convex-convex polygon intersection: O'Rourke vs CGAL\n";
    std::cout << "=================================================================\n";
    std::cout << "cases: " << cases.size()
              << "   repeats: " << repeats << "\n\n";

    int n_match  = 0;
    int n_diff   = 0;
    int n_both_empty = 0;
    int n_oorourke_empty_only = 0;

    // For aggregates.
    double total_orourke_ms = 0, total_cgal_ms = 0;
    std::size_t total_orourke_verts = 0, total_cgal_verts = 0;
    std::size_t max_orourke_ms_idx = 0;
    double max_orourke_ms = 0;

    std::cout << std::left
              << std::setw(34) << "case"
              << std::right
              << std::setw(8)  << "|P|"
              << std::setw(8)  << "|Q|"
              << std::setw(8)  << "|OR|"
              << std::setw(8)  << "|CG|"
              << std::setw(12) << "OR_ms"
              << std::setw(12) << "CG_ms"
              << std::setw(10) << "CG/OR"
              << std::setw(8)  << "match"
              << "\n";
    std::cout << std::string(108, '-') << "\n";

    for (std::size_t idx = 0; idx < cases.size(); idx++) {
        const auto& c = cases[idx];
        int reps = (c.P.size() + c.Q.size() < 32) ? repeats_small : repeats;
