// Force CCW orientation.
Polygon ensure_ccw(const Polygon& p) {
    if (signed_area(p) < 0) {
        Polygon r(p.rbegin(), p.rend());
        return r;
    }
    return p;
}

// Andrew's monotone-chain convex hull.  Returns CCW polygon (no collinear
// points on the boundary).  Used to compare two polygons that should be
// equal "up to redundant collinear vertices".
Polygon convex_hull(const Polygon& pts_in) {
    std::vector<Point> pts = pts_in;
    if (pts.size() <= 1) return pts;
    std::sort(pts.begin(), pts.end(),
              [](const Point& a, const Point& b) {
                  return a[0] < b[0] || (a[0] == b[0] && a[1] < b[1]);
              });
    auto cross = [](const Point& O, const Point& A, const Point& B) {
        return (A[0] - O[0]) * (B[1] - O[1]) -
               (A[1] - O[1]) * (B[0] - O[0]);
    };
    std::vector<Point> lower, upper;
    for (const auto& p : pts) {
        while (lower.size() >= 2 &&
               cross(lower[lower.size() - 2], lower.back(), p) <= 1e-12)
            lower.pop_back();
        lower.push_back(p);
    }
    for (auto it = pts.rbegin(); it != pts.rend(); ++it) {
        while (upper.size() >= 2 &&
               cross(upper[upper.size() - 2], upper.back(), *it) <= 1e-12)
            upper.pop_back();
        upper.push_back(*it);
    }
    lower.pop_back();
    upper.pop_back();
    Polygon hull = lower;
    hull.insert(hull.end(), upper.begin(), upper.end());
    return ensure_ccw(hull);
}

// Compare two polygons by their convex hull vertex sets (handles extra
// collinear vertices emitted by O'Rourke).
bool hulls_equal(const Polygon& A, const Polygon& B, double tol = 1e-6) {
    if (A.empty() && B.empty()) return true;
    if (A.empty() || B.empty()) return false;
    return polygons_equal(convex_hull(A), convex_hull(B), tol);
}

// Compare areas (handles the case where one algorithm returns a polygon
// whose vertices differ from the other but whose area is the same).
bool areas_match(const Polygon& A, const Polygon& B,
                  double abs_tol = 1e-6, double rel_tol = 1e-6) {
    double aA = std::fabs(signed_area(A));
    double aB = std::fabs(signed_area(B));
    if (aA < abs_tol && aB < abs_tol) return true;
    return std::fabs(aA - aB) <= abs_tol + rel_tol * std::max(aA, aB);
}

