// ===========================================================================
//  Loader: read a (F_poly, Gi_poly) dump produced by
//  `simplify --dump-intersect <id>`.  File format (text):
//
//      P <nP>
//      <x> <y>
//      ... <nP> lines ...
//      Q <nQ>
//      <x> <y>
//      ... <nQ> lines ...
//      <blank line>
//
//  Lines starting with '#' and blank lines between records are ignored.
//  Returns the parsed (P, Q) pairs.
// ===========================================================================

std::vector<TestCase> load_dump(const std::string& path, std::size_t cap = 0) {
    std::ifstream f(path);
    if (!f) {
        std::cerr << "Cannot open " << path << "\n";
        return {};
    }
    std::vector<TestCase> out;
    std::string tag;
    while (f >> tag) {
        if (tag == "#" || tag.empty()) {
            // skip rest of line
            f.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
            continue;
        }
        if (tag != "P" && tag != "Q") {
            // unknown line; skip
            f.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
            continue;
        }
        int n;
        if (!(f >> n)) break;
        Polygon poly;
        poly.reserve(n);
        for (int i = 0; i < n; i++) {
            double x, y;
            if (!(f >> x >> y)) { n = i; break; }
            poly.push_back({x, y});
        }
        if (tag == "P") {
            TestCase tc;
            tc.name = "dump_" + std::to_string(out.size());
            tc.P = std::move(poly);
            out.push_back(std::move(tc));
        } else {
            // Q: attach to the most recent record.
            if (!out.empty()) out.back().Q = std::move(poly);
        }
        if (cap && out.size() >= cap) break;
    }
    return out;
}

