std::vector<TestCase> load_dump(const std::string& path, std::size_t cap = 0) {
    std::ifstream f(path);
    if (!f) {
        std::cerr << "Cannot open " << path << "\n";
        return {};
    }
    std::vector<TestCase> out;
    std::string tag;
    while (f >> tag) {
        if (tag == "#" || tag.empty()) {
            // skip rest of line
            f.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
            continue;
        }
        if (tag != "P" && tag != "Q") {
            // unknown line; skip
            f.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
            continue;
        }
        int n;
        if (!(f >> n)) break;
        Polygon poly;
        poly.reserve(n);
        for (int i = 0; i < n; i++) {
            double x, y;
            if (!(f >> x >> y)) { n = i; break; }
            poly.push_back({x, y});
        }
        if (tag == "P") {
            TestCase tc;
            tc.name = "dump_" + std::to_string(out.size());
            tc.P = std::move(poly);
            out.push_back(std::move(tc));
        } else {
            // Q: attach to the most recent record.
            if (!out.empty()) out.back().Q = std::move(poly);
        }
        if (cap && out.size() >= cap) break;
    }
    return out;
}

// Like load_dump, but reads the whole file and returns only every Nth
// record (with a small head and tail included for variety).  This gives a
// representative slice of a large dump without paying for a full pass.
std::vector<TestCase> load_dump_stratified(const std::string& path,
                                             std::size_t target_count) {
    auto all = load_dump(path);
    if (target_count == 0 || all.size() <= target_count) return all;
    std::vector<TestCase> out;
    out.reserve(target_count);
    // Take the first ~10%, evenly-spaced middle samples, and the last ~10%.
    std::size_t head = std::max<std::size_t>(1, target_count / 10);
    std::size_t tail = std::max<std::size_t>(1, target_count / 10);
    std::size_t middle_count = target_count - head - tail;
    std::size_t middle_start = head;
    std::size_t middle_end = all.size() - tail;
    for (std::size_t i = 0; i < head; i++) out.push_back(all[i]);
    if (middle_count > 0 && middle_end > middle_start) {
        double step = double(middle_end - middle_start) / middle_count;
        for (std::size_t i = 0; i < middle_count; i++) {
            std::size_t idx = middle_start + std::size_t(i * step);
            if (idx >= all.size()) idx = all.size() - 1;
            out.push_back(all[idx]);
        }
    }
    for (std::size_t i = all.size() - tail; i < all.size(); i++) {
        out.push_back(all[i]);
    }
    return out;
}

