}  // namespace orourke

// ===========================================================================
//  Part 1b: O'Rourke's ConvexIntersect, with CGAL Filtered_kernel predicates
// ===========================================================================
//
// Same algorithm as `orourke::convex_intersect` (boundary-tracing, with
// the same Pin/Qin containment fallback and shared-edge special case), but
// every orientation/incidence test is replaced by an exact CGAL predicate
// from `Filtered_kernel<Simple_cartesian<double>>`.  This trades the
// speed of raw-double arithmetic for the robustness of CGAL's filtered
// exact-arithmetic fallback: when an orientation cannot be resolved at
// double precision, CGAL silently re-evaluates with exact integer
// arithmetic and returns the correct sign.
//
// The point of the exercise is to see how much of O'Rourke's real-data
// error rate is from the algorithm itself versus from floating-point
// degeneracy in the predicates.  If this version is correct where the
// raw-double version is wrong, the fix is "wrap the predicates in CGAL";
// if it still fails, O'Rourke's algorithmic logic is the problem.

namespace orourke_cgal {

using Kernel = CGAL::Filtered_kernel<CGAL::Simple_cartesian<double>>;
using Point  = std::array<double, 2>;
using Polygon = std::vector<Point>;
using CgalPoint = Kernel::Point_2;
using CgalVector = Kernel::Vector_2;
using CgalSign = Kernel::Sign;
using CgalSegment = Kernel::Segment_2;

static Point to_pt(const CgalPoint& p) {
    return {CGAL::to_double(p.x()), CGAL::to_double(p.y())};
}
static CgalPoint to_cgal(const Point& p) { return CgalPoint(p[0], p[1]); }

// ---------- predicates on CGAL points (exact, filtered) -----------------

// Sign of triangle area: +1 CCW, 0 collinear, -1 CW.
static int area_sign(const CgalPoint& a, const CgalPoint& b,
                       const CgalPoint& c) {
    auto s = CGAL::orientation(a, b, c);   // COLLINEAR / LEFT_TURN / RIGHT_TURN
    if (s == CGAL::LEFT_TURN)  return  1;
    if (s == CGAL::RIGHT_TURN) return -1;
    return 0;
}

static bool collinear(const CgalPoint& a, const CgalPoint& b,
                       const CgalPoint& c) {
    return CGAL::collinear(a, b, c);
}

static bool between(const CgalPoint& a, const CgalPoint& b,
                      const CgalPoint& c) {
    if (!collinear(a, b, c)) return false;
    // Range check on the dominant axis.  Done in plain double (these are
    // already on the same line so the test is exact for the typical case;
    // CGAL's collinear test is exact regardless).
    if (a.x() != b.x())
        return ((a.x() <= c.x() && c.x() <= b.x()) ||
                (a.x() >= c.x() && c.x() >= b.x()));
    return ((a.y() <= c.y() && c.y() <= b.y()) ||
            (a.y() >= c.y() && c.y() >= b.y()));
}

static int dot(const CgalVector& a, const CgalVector& b) {
    // CGAL::scalar_product returns an exact NT1; we only need the sign.
    auto v = a * b;
    return v > 0 ? 1 : (v < 0 ? -1 : 0);
}

// Classify the intersection of segments a->b and c->d.  Returns:
//   '0' = no intersection
//   '1' = proper intersection (one point, both s,t in (0,1))
//   'v' = endpoint touches (one of s,t is 0 or 1)
//   'e' = collinear overlap, returned as p,q
//   '?' = degenerate (no result)
static char seg_seg_int(const CgalPoint& a, const CgalPoint& b,
                          const CgalPoint& c, const CgalPoint& d,
                          CgalPoint& p, CgalPoint& q) {
    auto result = CGAL::intersection(CgalSegment(a, b), CgalSegment(c, d));
    if (!result) return '0';
    if (const CgalPoint* pt = std::get_if<CgalPoint>(&*result)) {
        p = *pt; return '1';
    }
    if (const CgalSegment* seg = std::get_if<CgalSegment>(&*result)) {
        // Collinear overlap.  Determine orientation for shared-edge
        // detection: dot of (b-a) and (d-c) is negative iff they point
        // in opposite directions.
        p = seg->source(); q = seg->target();
        return 'e';
    }
    return '?';
}

// Same parallel_int logic as orourke::parallel_int, but on CGAL points.
static char parallel_int(const CgalPoint& a, const CgalPoint& b,
                          const CgalPoint& c, const CgalPoint& d,
                          CgalPoint& p, CgalPoint& q) {
    if (!collinear(a, b, c)) return '0';

    if (between(a, b, c) && between(a, b, d)) { p = c; q = d; return 'e'; }
    if (between(c, d, a) && between(c, d, b)) { p = a; q = b; return 'e'; }
    if (between(a, b, c) && between(c, d, b)) { p = c; q = b; return 'e'; }
    if (between(a, b, c) && between(c, d, a)) { p = c; q = a; return 'e'; }
    if (between(a, b, d) && between(c, d, b)) { p = d; q = b; return 'e'; }
    if (between(a, b, d) && between(c, d, a)) { p = d; q = a; return 'e'; }
    return '0';
}

// Re-derivation of seg_seg_int in CGAL form: returns the proper/endpoint
// classification.  Falls back to parallel_int if the segments are
// collinear (CGAL::intersection handles that already, but we keep the
// call for consistency with the original C code's path).
static char seg_seg_int_classify(const CgalPoint& a, const CgalPoint& b,
                                    const CgalPoint& c, const CgalPoint& d,
                                    CgalPoint& p, CgalPoint& q) {
    return seg_seg_int(a, b, c, d, p, q);
}

// Advance: append `v` to output if `inside`, then return next index.
static int advance(int a, int& aa, int n, bool inside,
                    const CgalPoint& v, std::vector<CgalPoint>& output) {
    if (inside) output.push_back(v);
    aa++;
    return (a + 1) % n;
}

enum class InFlag { Pin, Qin, Unknown };

static InFlag in_out(InFlag inflag, int aHB, int bHA) {
    if      (aHB > 0) return InFlag::Pin;
    else if (bHA > 0) return InFlag::Qin;
    else              return inflag;
}

// Convex-polygon point-in-poly test using CGAL's exact left_turn predicate.
static bool point_in_convex_poly(const CgalPoint& p,
                                   const std::vector<CgalPoint>& poly) {
    int n = (int)poly.size();
    if (n == 0) return false;
    for (int i = 0; i < n; i++) {
        const auto& a = poly[i];
        const auto& b = poly[(i + 1) % n];
        if (!CGAL::left_turn(a, b, p)) return false;
    }
    return true;
}

// O'Rourke's ConvexIntersect, but with CGAL filtered predicates.
std::vector<CgalPoint> convex_intersect_cgal(const std::vector<CgalPoint>& Pin,
                                                const std::vector<CgalPoint>& Qin) {
    int n = (int)Pin.size();
    int m = (int)Qin.size();
    if (n < 3 || m < 3) return {};

    int a = 0, b = 0;
    int aa = 0, ba = 0;
    InFlag inflag = InFlag::Unknown;
    bool first_point = true;

    std::vector<CgalPoint> out;
    CgalPoint p0;
    bool shared_edge = false;
    CgalPoint shared_p, shared_q;

    auto finish = [&](bool closed) {
        if (closed && !first_point) out.push_back(p0);
    };

    do {
        int a1 = (a + n - 1) % n;
        int b1 = (b + m - 1) % m;

        CgalVector A = Pin[a]  - Pin[a1];
        CgalVector B = Qin[b]  - Qin[b1];

        CgalPoint origin(0, 0);
        int cross = area_sign(origin, A, B);
        int aHB   = area_sign(Qin[b1], Qin[b], Pin[a]);
        int bHA   = area_sign(Pin[a1], Pin[a], Qin[b]);

        CgalPoint p, q;
        char code = seg_seg_int_classify(Pin[a1], Pin[a],
                                            Qin[b1], Qin[b], p, q);

        if (code == '1' || code == 'v') {
            if (inflag == InFlag::Unknown && first_point) {
                aa = ba = 0;
                first_point = false;
                p0 = p;
            }
            out.push_back(p);
            inflag = in_out(inflag, aHB, bHA);
        }

        // Shared edge: A & B collinear overlap with opposite orientation
        if ((code == 'e') && (dot(A, B) < 0)) {
            shared_edge = true;
            shared_p = p; shared_q = q;
            break;
        }

        // Parallel and separated -> disjoint
        if ((cross == 0) && (aHB < 0) && (bHA < 0)) {
            return {};
        }

        // Collinear with coincident boundary -> advance without printing
        if ((cross == 0) && (aHB == 0) && (bHA == 0)) {
            if (inflag == InFlag::Pin)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qin[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pin[a], out);
        } else if (cross >= 0) {
            if (bHA > 0)
                a = advance(a, aa, n, inflag == InFlag::Pin, Pin[a], out);
            else
                b = advance(b, ba, m, inflag == InFlag::Qin, Qin[b], out);
        } else {  // cross < 0
            if (aHB > 0)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qin[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pin[a], out);
        }
    } while (((aa < n) || (ba < m)) && (aa < 2 * n) && (ba < 2 * m));

    if (shared_edge) {
        out.push_back(shared_p);
        out.push_back(shared_q);
    } else {
        finish(!first_point);
    }

    if (inflag == InFlag::Unknown && first_point) {
        // Boundaries don't cross: containment or single-point touch.
        if (point_in_convex_poly(Pin[0], Qin)) {
            return Pin;
        }
        if (point_in_convex_poly(Qin[0], Pin)) {
            return Qin;
        }
        return {};
    }

    // Strip trailing duplicate (== p0) if any
    if (out.size() >= 2) {
        const auto& first = out.front();
        const auto& last  = out.back();
        if (first == last) out.pop_back();
    }
    return out;
}

// Public entry point: takes the same std::vector<std::array<double,2>>
// shape as the other two algorithms, and returns the same shape.
Polygon convex_intersect(const Polygon& Pin, const Polygon& Qin) {
    std::vector<CgalPoint> P, Q;
    P.reserve(Pin.size()); Q.reserve(Qin.size());
    for (auto& v : Pin) P.push_back(to_cgal(v));
    for (auto& v : Qin) Q.push_back(to_cgal(v));
    auto out = convex_intersect_cgal(P, Q);
    Polygon result;
    result.reserve(out.size());
    for (auto& v : out) result.push_back(to_pt(v));
    return result;
}

