    bool vtx_match  = polygons_equal(ensure_ccw(orourke_out),
                                      ensure_ccw(cgal_out));
    bool hul_match  = hulls_equal(orourke_out, cgal_out);
    bool area_match = areas_match(orourke_out, cgal_out);

    // OR-CGAL vs canonical CGAL
    bool oc_hul_match  = hulls_equal(orourke_cgal_out, cgal_out);
    bool oc_area_match = areas_match(orourke_cgal_out, cgal_out);

    if (both_empty) n_both_empty++;
    if (vtx_match)  n_match++;
    else            n_diff++;
    if (hul_match)  n_hull_match++;
    if (area_match) n_area_match++;
    else if (!both_empty) n_area_mismatch++;
    if (orourke_out.empty() && !cgal_out.empty())
        n_oorourke_empty_only++;

    if (oc_hul_match)  n_orourke_cgal_hull_match++;
    if (oc_area_match) n_orourke_cgal_area_match++;
    else if (!(orourke_cgal_out.empty() && cgal_out.empty()))
        n_orourke_cgal_area_mismatch++;
    if (orourke_cgal_out.empty() && !cgal_out.empty())
        n_orourke_cgal_empty_only++;

    total_orourke_ms   += t_orourke;
    total_cgal_ms      += t_cgal;
    total_orourke_cgal_ms += t_orourke_cgal;
    total_orourke_verts += orourke_out.size();
    total_cgal_verts    += cgal_out.size();
    total_orourke_cgal_verts += orourke_cgal_out.size();
    if (t_orourke > max_orourke_ms) {
        max_orourke_ms = t_orourke;
        max_orourke_ms_idx = idx;
    }

    // Update bucket
    int b = bucket_idx(c.P.size() + c.Q.size());
    if (b >= MAX_BUCKETS) b = MAX_BUCKETS - 1;
    buckets[b].count++;
    buckets[b].sum_orourke     += t_orourke;
    buckets[b].sum_cgal        += t_cgal;
    buckets[b].sum_orourke_cgal += t_orourke_cgal;
    if (!vtx_match) buckets[b].vertex_mismatch++;
    if (!area_match && !both_empty) buckets[b].area_mismatch++;
    if (!oc_area_match && !(orourke_cgal_out.empty() && cgal_out.empty()))
        buckets[b].orourke_cgal_area_mismatch++;

    if (print_table) {
        char vtx_ch  = vtx_match  ? 'Y' : (both_empty ? '-' : 'n');
        char area_ch = area_match ? 'Y' : (both_empty ? '-' : 'n');
        char oc_vtx_ch  = oc_hul_match  ? 'Y' : ((orourke_cgal_out.empty() && cgal_out.empty()) ? '-' : 'n');
        char oc_area_ch = oc_area_match ? 'Y' : ((orourke_cgal_out.empty() && cgal_out.empty()) ? '-' : 'n');

        std::cout << std::left
                  << std::setw(34) << c.name
                  << std::right
                  << std::setw(6)  << c.P.size()
                  << std::setw(6)  << c.Q.size()
                  << std::setw(6)  << orourke_out.size()
                  << std::setw(6)  << orourke_cgal_out.size()
                  << std::setw(6)  << cgal_out.size()
                  << std::setw(10) << t_orourke
                  << std::setw(10) << t_orourke_cgal
                  << std::setw(10) << t_cgal
                  << std::setw(8)  << (t_cgal > 0 ? t_orourke / t_cgal : 0)
                  << std::setw(8)  << (t_cgal > 0 ? t_orourke_cgal / t_cgal : 0)
                  << std::setw(5)  << vtx_ch
                  << std::setw(5)  << area_ch
                  << std::setw(5)  << oc_vtx_ch
                  << std::setw(5)  << oc_area_ch
                  << "\n";
    }
}

