// ===========================================================================
//  O'Rourke's ConvexIntersect (Ch. 7, "Computational Geometry in C", 2nd ed.)
//  with CGAL Exact_predicates_inexact_constructions_kernel (Epick) replacing
//  every orientation / incidence / segment-intersection decision.  Epick
//  gives exact predicates (orientation, collinearity, betweenness) but
//  uses double arithmetic for constructions, so each per-iteration call
//  is much cheaper than the exact-constructions Epeck used elsewhere in
//  this file.  Every value produced is consumed by another exact predicate
//  downstream, so inexact constructions are safe.
//
//  Result contract is identical to `intersect()` above: the intersection
//  polygon (if any) is emitted as a single Polygon_with_holes into `result`.
//  Coordinates crossing the namespace boundary are converted to the file-
//  wide Kernel::Point_2 (Epeck) at the very end, so the rest of simplify.cpp
//  is unaffected.
// ===========================================================================
namespace orourke_cgal {

enum class InFlag { Pin, Qin, Unknown };

// Local point type.  Shadowing the file-wide `Point` keeps the O'Rourke
// code below readable, but every external use of this namespace must
// convert via the helpers at the bottom of the file.
using Point = Epick_Point;
using Segment = Epick_Segment;
using Vector = Epick_Vector;

// Exact orientation sign (-1, 0, +1) of (a, b, c).  Uses Epick's
// exact-predicate orientation, so the sign is correct even for nearly-
// collinear input.
static int area_sign(const Point& a, const Point& b, const Point& c) {
    switch (CGAL::orientation(a, b, c)) {
        case CGAL::LEFT_TURN:  return  1;
        case CGAL::RIGHT_TURN: return -1;
        case CGAL::COLLINEAR:  return  0;
    }
    return 0;
}

// Same as area_sign but for vector triples.  Used inside the main loop
// where A and B are the *edge vectors* of the two polygons, not points.
static int area_sign_vec(const Vector& a, const Vector& b) {
    // Cross product sign of (a, b).  In Epick the cross product is exact
    // (the kernel is exact-predicate), so a sign test on CGAL::cross_product
    // is correct.
    auto c = CGAL::cross_product(a, b);
    if (c > 0) return  1;
    if (c < 0) return -1;
    return 0;
}

// Is c on the closed segment ab?  Exact collinearity test, then exact
// dominance test on whichever coordinate has the larger dynamic range.
static bool between(const Point& a, const Point& b, const Point& c) {
    if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) return false;
    if (CGAL::abs(b.x() - a.x()) >= CGAL::abs(b.y() - a.y())) {
        return (a.x() <= c.x() && c.x() <= b.x()) ||
               (a.x() >= c.x() && c.x() >= b.x());
    }
    return (a.y() <= c.y() && c.y() <= b.y()) ||
           (a.y() >= c.y() && c.y() >= b.y());
}

// Sign of the inner product (b - a) . (d - c).  Used by the shared-edge
// special case to detect "edges overlap with opposite orientation".
static int dot_sign(const Point& a, const Point& b,
                    const Point& c, const Point& d) {
    auto ux = b.x() - a.x(), uy = b.y() - a.y();
    auto vx = d.x() - c.x(), vy = d.y() - c.y();
    auto s  = ux * vx + uy * vy;
    if (s > 0) return  1;
    if (s < 0) return -1;
    return 0;
}

// Handle parallel/collinear segments ab and cd.  Returns one of:
//   '0' - no intersection
//   'e' - collinear overlap; out_p, out_q are the two overlap endpoints
static char parallel_int(const Point& a, const Point& b,
                         const Point& c, const Point& d,
                         Point& out_p, Point& out_q) {
    if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) return '0';

    if (between(a, b, c) && between(a, b, d)) { out_p = c; out_q = d; return 'e'; }
    if (between(c, d, a) && between(c, d, b)) { out_p = a; out_q = b; return 'e'; }
    if (between(a, b, c) && between(c, d, b)) { out_p = c; out_q = b; return 'e'; }
    if (between(a, b, c) && between(c, d, a)) { out_p = c; out_q = a; return 'e'; }
    if (between(a, b, d) && between(c, d, b)) { out_p = d; out_q = b; return 'e'; }
    if (between(a, b, d) && between(c, d, a)) { out_p = d; out_q = a; return 'e'; }
    return '0';
}

// Segment-segment intersection.  Returns one of:
//   '0' - no intersection
//   'v' - endpoint touches the other segment (single point in out_p)
//   '1' - proper crossing (single point in out_p)
//   'e' - collinear overlap (two endpoints in out_p, out_q)
static char seg_seg_int(const Point& a, const Point& b,
                        const Point& c, const Point& d,
                        Point& out_p, Point& out_q) {
    // Use Epick::Segment_2 for the intersection.  CGAL's kernel gives
    // exact predicates on Segment, so when the result is a single Point
    // we know it's the unique intersection.  Inexact construction only
    // matters for the result coordinates themselves (which become inputs
    // to the next predicate), and the predicate is exact.
    auto inter = CGAL::intersection(Segment(a, b), Segment(c, d));
    if (!inter) return '0';
    if (const Point* ip = std::get_if<Point>(&*inter)) {
        // Distinguish 'v' (endpoint) from '1' (proper crossing) by checking
        // whether the point is an endpoint of either segment.
        bool on_a = CGAL::squared_distance(*ip, a) == 0 ||
                    CGAL::squared_distance(*ip, b) == 0;
        bool on_c = CGAL::squared_distance(*ip, c) == 0 ||
                    CGAL::squared_distance(*ip, d) == 0;
        out_p = *ip;
        return (on_a || on_c) ? 'v' : '1';
    }
    if (const Segment* seg = std::get_if<Segment>(&*inter)) {
        out_p = seg->source();
        out_q = seg->target();
        return 'e';
    }
    return '0';
}

// Advance the index for polygon P or Q depending on `inside`, and append
// the appropriate vertex to `out` if `inside` is true.  Returns the new index.
static int advance(int a, int& aa, int n, bool inside,
                   const Point& v, std::vector<Point>& out) {
    if (inside) out.push_back(v);
    aa++;
    return (a + 1) % n;
}

static InFlag in_out(const Point& /*p*/, InFlag inflag, int aHB, int bHA) {
    if      (aHB > 0) return InFlag::Pin;
    else if (bHA > 0) return InFlag::Qin;
    return inflag;
}

// Point-in-convex-polygon test, used only for the "boundaries don't cross"
// closure (one polygon entirely inside the other, or single touching point).
static bool point_in_convex_poly(const Point& p, const std::vector<Point>& poly) {
    int n = (int)poly.size();
    for (int i = 0; i < n; ++i) {
        const Point& a = poly[i];
        const Point& b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == CGAL::RIGHT_TURN) return false;
    }
    return true;
}

// O'Rourke's ConvexIntersect, adapted.  Returns the intersection polygon
// vertices in CCW order.  If P is contained in Q (or vice versa) and they
// share no boundary crossings, the inner polygon's vertices are returned
// verbatim.
static std::vector<Point> convex_intersect(const std::vector<Point>& Pin,
                                           const std::vector<Point>& Qin) {
    int n = (int)Pin.size();
    int m = (int)Qin.size();
    if (n < 3 || m < 3) return {};

    int a = 0, b = 0;
    int aa = 0, ba = 0;
    InFlag inflag = InFlag::Unknown;
    bool first_point = true;

    std::vector<Point> out;
    Point p0;
    bool shared_edge = false;          // 'e'-overlap with opposite orientation
    Point shared_p, shared_q;

    auto finish = [&](bool closed) {
        if (closed && !first_point) out.push_back(p0);
    };

    do {
        int a1 = (a + n - 1) % n;
        int b1 = (b + m - 1) % m;

        // Edge vectors A, B.  Epick provides Vector_2 for point - point.
        Vector A = Pin[a] - Pin[a1];
        Vector B = Qin[b] - Qin[b1];

        int cross = area_sign_vec(A, B);
        int aHB   = area_sign(Qin[b1], Qin[b], Pin[a]);
        int bHA   = area_sign(Pin[a1], Pin[a], Qin[b]);

        Point p, q;
        char code = seg_seg_int(Pin[a1], Pin[a], Qin[b1], Qin[b], p, q);

        if (code == '1' || code == 'v') {
            if (inflag == InFlag::Unknown && first_point) {
                aa = ba = 0;
                first_point = false;
                p0 = p;
            }
            out.push_back(p);
            inflag = in_out(p, inflag, aHB, bHA);
        }

        // Special case: A & B overlap and oppositely oriented -> shared edge
        if ((code == 'e') && (dot_sign(Pin[a1], Pin[a], Qin[b1], Qin[b]) < 0)) {
            shared_edge = true;
            shared_p = p;
            shared_q = q;
            break;
        }

        // Special case: A & B parallel and separated
        if ((cross == 0) && (aHB < 0) && (bHA < 0)) {
            return {};
        }

        // Special case: A & B collinear -> advance without printing
        if ((cross == 0) && (aHB == 0) && (bHA == 0)) {
            if (inflag == InFlag::Pin)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qin[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pin[a], out);
        } else if (cross >= 0) {
            if (bHA > 0)
                a = advance(a, aa, n, inflag == InFlag::Pin, Pin[a], out);
            else
                b = advance(b, ba, m, inflag == InFlag::Qin, Qin[b], out);
        } else {  // cross < 0
            if (aHB > 0)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qin[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pin[a], out);
        }
    } while (((aa < n) || (ba < m)) && (aa < 2 * n) && (ba < 2 * m));

    if (shared_edge) {
        out.push_back(shared_p);
        out.push_back(shared_q);
    } else {
        finish(!first_point);
    }

    if (inflag == InFlag::Unknown && first_point) {
        // Boundaries do not cross: P is inside Q, or Q is inside P, or they
        // touch at a single point.  Detect containment by sampling one
        // vertex of P.
        if (point_in_convex_poly(Pin[0], Qin)) return Pin;
        if (point_in_convex_poly(Qin[0], Pin)) return Qin;
        return {};
    }

    return out;
}

}  // namespace orourke_cgal

// Convert a single Kernel::Point_2 (Epeck) to an Epick::Point_2.
static Epick_Point to_epick(const Kernel::Point_2& p) {
    return Epick_Point(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
}

// Convert a single Epick::Point_2 back to a Kernel::Point_2 (Epeck).  The
// result is exact because Epeck's Point_2 stores a lazy exact representation
// of its double coordinates, so no precision is lost in the round trip.
static Kernel::Point_2 from_epick(const Epick_Point& p) {
    return Kernel::Point_2(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
}

// intersect_OR: same contract as intersect() (above), but uses
// O'Rourke's algorithm with CGAL Epick exact predicates.  Used by the
// `--intersect orourke` runtime mode.
static void intersect_OR(const Polygon& subject, const Polygon& clip,
                          std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    std::vector<Epick_Point> P_verts, Q_verts;
    P_verts.reserve(subject.size());
    Q_verts.reserve(clip.size());
    for (auto it = subject.vertices_begin(); it != subject.vertices_end(); ++it) {
        P_verts.push_back(to_epick(*it));
    }
    for (auto it = clip.vertices_begin(); it != clip.vertices_end(); ++it) {
        Q_verts.push_back(to_epick(*it));
    }

    auto verts = orourke_cgal::convex_intersect(P_verts, Q_verts);
    if (verts.size() < 3) return;

    std::vector<Kernel::Point_2> result_verts;
    result_verts.reserve(verts.size());
    for (const auto& v : verts) {
        result_verts.push_back(from_epick(v));
    }

    Polygon inter_poly(result_verts.begin(), result_verts.end());
    if (!inter_poly.is_simple()) return;
    if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();

    *result++ = Polygon_with_holes(inter_poly);
}

