// Quick test: build a polygon pair where the "parallel and separated"
// early return would fire wrongly, and check if removing it fixes things.

#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <CGAL/Polygon_2.h>
#include <CGAL/intersections.h>
#include <CGAL/convex_hull_2.h>
#include <CGAL/Kernel/global_functions.h>

#include <cstdio>
#include <cstdlib>
#include <vector>
#include <random>

using K = CGAL::Exact_predicates_inexact_constructions_kernel;
using Point = K::Point_2;
using Polygon = CGAL::Polygon_2<K>;
using Vector = K::Vector_2;

// Replicate the O'Rourke helpers from simplify.cpp orourke_cgal namespace
namespace tt {
using InFlag = int;  // 0=Pin, 1=Qin, 2=Unknown

static int area_sign(const Point& a, const Point& b, const Point& c) {
    auto o = CGAL::orientation(a, b, c);
    return o == CGAL::LEFT_TURN ? 1 : (o == CGAL::RIGHT_TURN ? -1 : 0);
}
static int area_sign_vec(const Vector& A, const Vector& B) {
    auto o = CGAL::orientation(Vector(0,0), A, B);
    return o == CGAL::LEFT_TURN ? 1 : (o == CGAL::RIGHT_TURN ? -1 : 0);
}
static int dot_sign(const Point& a, const Point& b, const Point& c, const Point& d) {
    auto v1 = b - a;
    auto v2 = d - c;
    K::FT dot = v1 * v2;
    return dot > 0 ? 1 : (dot < 0 ? -1 : 0);
}

// CGAL predicates wrapper matching simplify.cpp seg_seg_int
static char seg_seg_int(const Point& a, const Point& b,
                        const Point& c, const Point& d,
                        Point& out_p, Point& out_q) {
    auto inter = CGAL::intersection(Segment(a, b), Segment(c, d));
    if (!inter) return '0';
    if (const Point* ip = std::get_if<Point>(&*inter)) {
        bool on_a = CGAL::squared_distance(*ip, a) == 0 ||
                    CGAL::squared_distance(*ip, b) == 0;
        bool on_c = CGAL::squared_distance(*ip, c) == 0 ||
                    CGAL::squared_distance(*ip, d) == 0;
        out_p = *ip;
        return (on_a || on_c) ? 'v' : '1';
    }
    if (const Segment* seg = std::get_if<Segment>(&*inter)) {
        out_p = seg->source();
        out_q = seg->target();
        return 'e';
    }
    return '0';
}

using InFlagT = int;
static InFlagT in_out(const Point& p, InFlagT inflag, int aHB, int bHA) {
    (void)p;
    if (aHB > 0) return 0;
    if (bHA > 0) return 1;
    return inflag;
}

static int advance(int a, int& aa, int n, bool inside,
                   const Point& v, std::vector<Point>& out) {
    if (inside) out.push_back(v);
    aa++;
    return (a + 1) % n;
}

static bool point_in_convex_poly(const Point& p, const std::vector<Point>& poly) {
    int n = (int)poly.size();
    for (int i = 0; i < n; ++i) {
        if (CGAL::orientation(poly[i], poly[(i+1)%n], p) == CGAL::RIGHT_TURN) return false;
    }
    return true;
}

// Faithful port of simplify.cpp:convex_intersect
static std::vector<Point> convex_intersect(const std::vector<Point>& Pin,
                                           const std::vector<Point>& Qin) {
    int n = (int)Pin.size();
    int m = (int)Qin.size();
    if (n < 3 || m < 3) return {};

    int a = 0, b = 0;
    int aa = 0, ba = 0;
    InFlagT inflag = 2;
    bool first_point = true;

    std::vector<Point> out;
    Point p0;
    bool shared_edge = false;
    Point shared_p, shared_q;

    auto finish = [&](bool closed) {
        if (closed && !first_point) out.push_back(p0);
    };

    do {
        int a1 = (a + n - 1) % n;
        int b1 = (b + m - 1) % m;
        Vector A = Pin[a] - Pin[a1];
        Vector B = Qin[b] - Qin[b1];
        int cross = area_sign_vec(A, B);
        int aHB   = area_sign(Qin[b1], Qin[b], Pin[a]);
        int bHA   = area_sign(Pin[a1], Pin[a], Qin[b]);

        Point p, q;
        char code = seg_seg_int(Pin[a1], Pin[a], Qin[b1], Qin[b], p, q);

        if (code == '1' || code == 'v') {
            if (inflag == 2 && first_point) {
                aa = ba = 0;
                first_point = false;
                p0 = p;
            }
            out.push_back(p);
            inflag = in_out(p, inflag, aHB, bHA);
        }

        if ((code == 'e') && (dot_sign(Pin[a1], Pin[a], Qin[b1], Qin[b]) < 0)) {
            shared_edge = true;
            shared_p = p;
            shared_q = q;
            break;
        }

        if ((cross == 0) && (aHB < 0) && (bHA < 0)) {
            return {};  // <-- THE BUG UNDER TEST
        }

        if ((cross == 0) && (aHB == 0) && (bHA == 0)) {
            if (inflag == 0)
                b = advance(b, ba, m, inflag == 1, Qin[b], out);
            else
                a = advance(a, aa, n, inflag == 0, Pin[a], out);
        } else if (cross >= 0) {
            if (bHA > 0)
                a = advance(a, aa, n, inflag == 0, Pin[a], out);
            else
                b = advance(b, ba, m, inflag == 1, Qin[b], out);
        } else {
            if (aHB > 0)
                b = advance(b, ba, m, inflag == 1, Qin[b], out);
            else
                a = advance(a, aa, n, inflag == 0, Pin[a], out);
        }
    } while (((aa < n) || (ba < m)) && (aa < 2 * n) && (ba < 2 * m));

    if (shared_edge) {
        out.push_back(shared_p);
        out.push_back(shared_q);
    } else {
        finish(!first_point);
    }

    if (inflag == 2 && first_point) {
        if (point_in_convex_poly(Pin[0], Qin)) return Pin;
        if (point_in_convex_poly(Qin[0], Pin)) return Qin;
        return {};
    }
    return out;
}

// Same but without the early return
static std::vector<Point> convex_intersect_fixed(const std::vector<Point>& Pin,
                                                 const std::vector<Point>& Qin) {
    int n = (int)Pin.size();
    int m = (int)Qin.size();
    if (n < 3 || m < 3) return {};

    int a = 0, b = 0;
    int aa = 0, ba = 0;
    InFlagT inflag = 2;
    bool first_point = true;

    std::vector<Point> out;
    Point p0;

    auto finish = [&](bool closed) {
        if (closed && !first_point) out.push_back(p0);
    };

    do {
        int a1 = (a + n - 1) % n;
        int b1 = (b + m - 1) % m;
        Vector A = Pin[a] - Pin[a1];
        Vector B = Qin[b] - Qin[b1];
        int cross = area_sign_vec(A, B);
        int aHB   = area_sign(Qin[b1], Qin[b], Pin[a]);
        int bHA   = area_sign(Pin[a1], Pin[a], Qin[b]);

        Point p, q;
        char code = seg_seg_int(Pin[a1], Pin[a], Qin[b1], Qin[b], p, q);

