// O'Rourke's ConvexIntersect, adapted.  Returns the intersection polygon
// vertices in CCW order.  If P is contained in Q (or vice versa) and they
// share no boundary crossings, the inner polygon's vertices are returned
// verbatim.
static std::vector<Point> convex_intersect(const std::vector<Point>& Pin,
                                           const std::vector<Point>& Qin) {
    int n = (int)Pin.size();
    int m = (int)Qin.size();
    if (n < 3 || m < 3) return {};

    // Winding normalization: O'Rourke's algorithm assumes both polygons
    // are CCW.  A CW polygon flips every aHB/bHA sign, which silently
    // rotates the algorithm the wrong way around and produces a wrong
    // (often empty) result.  Detect CW input by signed area and reverse
    // the vertex order in place.  This makes the main loop robust to
    // caller winding without changing its core logic.
    auto signed_area = [](const std::vector<Point>& P) {
        K::FT s = 0;
        int sz = (int)P.size();
        for (int i = 0; i < sz; ++i) {
            const Point& a = P[i];
            const Point& b = P[(i + 1) % sz];
            s += (a.x() * b.y() - b.x() * a.y());
        }
        return s / 2;
    };
    std::vector<Point> Pin_n = Pin;
    std::vector<Point> Qin_n = Qin;
    if (signed_area(Pin_n) < 0) {
        std::reverse(Pin_n.begin(), Pin_n.end());
    }
    if (signed_area(Qin_n) < 0) {
        std::reverse(Qin_n.begin(), Qin_n.end());
    }
    auto& Pr = Pin_n;
    auto& Qr = Qin_n;
    n = (int)Pr.size();
    m = (int)Qr.size();

    int a = 0, b = 0;
    int aa = 0, ba = 0;
    InFlag inflag = InFlag::Unknown;
    bool first_point = true;

    std::vector<Point> out;
    Point p0;
    bool shared_edge = false;          // 'e'-overlap with opposite orientation
    Point shared_p, shared_q;

    auto finish = [&](bool closed) {
        if (closed && !first_point) out.push_back(p0);
    };

    do {
        int a1 = (a + n - 1) % n;
        int b1 = (b + m - 1) % m;

        // Edge vectors A, B.  Epick provides Vector_2 for point - point.
        Vector A = Pr[a] - Pr[a1];
        Vector B = Qr[b] - Qr[b1];

        int cross = area_sign_vec(A, B);
        int aHB   = area_sign(Qr[b1], Qr[b], Pr[a]);
        int bHA   = area_sign(Pr[a1], Pr[a], Qr[b]);

        Point p, q;
        char code = seg_seg_int(Pr[a1], Pr[a], Qr[b1], Qr[b], p, q);

        if (code == '1' || code == 'v') {
            if (inflag == InFlag::Unknown && first_point) {
                aa = ba = 0;
                first_point = false;
                p0 = p;
