        // touch at a single point.  Detect containment by sampling one
        // vertex of P.  (The Pin_n/Qin_n winding normalization above
        // means we can use the strict CCW point-in-convex-poly test.)
        if (point_in_convex_poly(Pr[0], Qr)) return Pr;
        if (point_in_convex_poly(Qr[0], Pr)) return Qr;
